window.BUILDS=[{"n":1,"slug":"atelier-voss","kind":"site","lane":"quiet","trade":"Architecture practice","mobile":true,"group":"Websites · Quiet","name":"Atelier Voss","biz":"Architecture practice","c":"#2B59FF","sheet":"#E1E8FF","cInk":"#FFFFFF","cText":"#2B59FF","short":"An architecture practice whose four projects sit beside the drawings that made them.","long":"The name runs huge across a photo of a finished house. Below it, four projects each get a full chapter: the real building on one side, and on the other the plan, section or elevation drawing itself in as you scroll. Tap a number on the drawing and the same spot lights up on the photo. Enquiries go in on the practice's own title block.","proves":"Real photography and technical drawing on the same page, so a visitor sees both the finished building and the thinking behind it.","tags":["Real buildings beside their drawings","Drawings that draw as you scroll","An enquiry on a title block"],"tk":"creative","show":[{"wait":2200,"say":"The name over a finished building"},{"scroll":"#halvard .dw","say":"The plan draws itself as you scroll"},{"tap":"#halvard .keys button[data-n=\"3\"]","say":"Tap a number to find it in the photo"},{"scroll":"#cloister .dw","say":"A section that decides where the sun lands"},{"tap":"#kinds .chip[data-k=conv]","say":"Enquiries go in on a title block"}]},{"n":2,"slug":"cadence","kind":"site","lane":"direct","trade":"Software company","mobile":true,"group":"Websites · Direct","name":"Cadence","biz":"Field-ops software","c":"#FFB300","sheet":"#FFF4DB","cInk":"#141416","cText":"#91680A","short":"The page is an operations board that never stops running.","long":"A departure board under tungsten light: the board is the hero, the headline is a card pinned inside it, ETAs flip like split-flap cells, and a whole shift plays out as you scroll. Pricing is a line-items table.","proves":"A product page where the product is the page.","tags":["Self-playing board","Split-flap cells","Signal amber"],"tk":"software","show":[{"tap":"#chipFilter","say":"Show only the blocked jobs"},{"tap":"#chipAll","say":"Back to the whole board"},{"scrollBy":1600,"dur":3600,"say":"Scroll: the shift plays out"}]},{"n":3,"slug":"maree","kind":"site","lane":"motion","trade":"Fragrance house","mobile":true,"group":"Websites · Motion","name":"Marée","biz":"Fragrance house","c":"#A9CBBD","sheet":"#F3F8F6","cInk":"#141416","cText":"#63756F","short":"A real bottle on a black stage, ink in the water, and a clock for the notes.","long":"One photograph of the bottle on dark stone, with ink drifting slowly through the water around it. The notes are five short lines on a wear clock: slide through eleven hours on skin and the ones you would smell light up. Then straight to three sizes and a bag that knows when the bottle is filled and when it reaches you.","proves":"Luxury that sells, without a single gold gradient.","tags":["A real bottle on a black stage","Ink drifting through the water","A wear clock for the notes"],"tk":"creative","show":[{"wait":2200,"say":"Ink drifting over the bottle"},{"scroll":"#clock","say":"Slide through a day on skin"},{"tap":"#jumps button[data-h=\"7\"]","say":"At seven hours, iris and birch smoke lead"},{"tap":".size[data-s=\"100\"]","say":"Pick a size"},{"tap":"#addBtn","say":"The bag knows when it is filled and when it arrives"}]},{"n":4,"slug":"signal","kind":"site","lane":"loud","trade":"Festival","mobile":true,"group":"Websites · Loud","name":"SIGNAL 2027","biz":"Music & light festival","c":"#3B18E0","sheet":"#E4DFFB","cInk":"#FFFFFF","cText":"#3B18E0","short":"Type that reacts to how hard you scroll.","long":"Three days of sound, code and light. Marquees whose speed and skew answer your scrolling, headlines that rise into place, an RGB fringe on the display type because the identity is light being split, and a live countdown in enormous tabular numerals.","proves":"Loud, and still not a template.","tags":["Scroll-velocity type","RGB fringe","Live countdown"],"tk":"creative","show":[{"scrollBy":2200,"dur":3800,"say":"Scroll through the festival"},{"tap":"button[data-day=\"1\"]","say":"Filter the line-up by day"}]},{"n":5,"slug":"long-exposure","kind":"site","lane":"motion","trade":"Film production company","mobile":true,"group":"Websites · Motion","name":"Long Exposure","biz":"Film production, Manchester","c":"#E8E8E8","sheet":"#FCFCFC","cInk":"#141416","cText":"#6F6F70","short":"A film company whose first screen is its showreel, with the timecode and scrub bar on top.","long":"A four-person production company in black and white, with one red REC dot. The first screen is a showreel cut from four of this year's jobs, with a running timecode and a scrub bar laid over the footage, one segment per job. Below it the four jobs play on hover or as they scroll into view, a still from a night shoot runs edge to edge, and the services are set out as a real call sheet dated next Tuesday. Add a line and it goes straight onto a request that comes back as a call sheet of its own.","proves":"A film company's site can open on the film, and still take the enquiry.","tags":["A real showreel in the first screen","Timecode and a scrub bar on the footage","Jobs that play as you pass"],"tk":"creative","show":[{"wait":2600,"say":"The showreel is the first screen"},{"tap":"#scrub","say":"Scrub straight to a job"},{"scroll":"#works","say":"Each job plays as you pass"},{"tap":"#shRows .add[data-k=brand]","say":"Add a line from the call sheet"}]},{"n":6,"slug":"overhead","kind":"site","lane":"motion","trade":"Drone survey & filming","mobile":true,"group":"Websites · Motion","name":"Overhead","biz":"Drone survey, Peak District","c":"#FF6A13","sheet":"#FFEADE","cInk":"#141416","cText":"#BF5314","short":"A drone survey firm whose survey lines draw themselves over real aerial photos as you scroll.","long":"A two-person drone survey outfit in slate and cloud with one hi-vis orange for booking. The first screen is a real aerial film flown over Peak District fields. Below it, three real stills show what the client actually gets back: half-metre contours and a boundary on a field, a measured roof with six numbered defects, and cut and spoil on a building site, each drawing itself over the photo as you scroll. Four fixed prices carry straight into an enquiry that checks the postcode and says who rings back and when.","proves":"A survey firm can show what it hands over, not just a gallery of aerial photos.","tags":["Aerial film in the first screen","Survey lines that draw as you scroll","A flight log worked out from today"],"tk":"creative","show":[{"scroll":"#survey .viewer","say":"The survey draws itself over the real photo"},{"tap":".tab[data-t=roof]","say":"A roof, measured, with every defect numbered"},{"tap":".tab[data-t=site]","say":"Cut and spoil on a building site, month by month"},{"scroll":"#log .log","say":"The last six flying days, dated from today"}]},{"n":7,"slug":"southpaw","kind":"site","lane":"loud","trade":"Boxing club","mobile":true,"group":"Websites · Loud","name":"Southpaw","biz":"Boxing club, Leeds","c":"#E5232E","sheet":"#FBE0E2","cInk":"#FFFFFF","cText":"#E5232E","short":"A boxing club site run by a live round timer, with the week straight under it.","long":"Ring black, chalk white and one corner red. The first screen is a real ringside photo and a working round timer (start, pause, reset, twelve three-minute rounds with a minute's rest), with this week's timetable straight underneath and tonight's next bell worked out from the visitor's own clock. Booking a free first session starts with four photo tiles, so a beginner and a parent each see themselves before they pick a day.","proves":"Somebody who has never boxed can pick a level, pick a night this week and be booked in about twenty seconds.","tags":["Working round timer","Live timetable","Photo-led booking"],"tk":"gym","show":[{"wait":2200,"say":"The round timer is already running"},{"scroll":"#levelOpts","say":"Tell them where you are starting from"},{"tap":"button[data-level=new]","say":"Never boxed: this week's beginners' sessions"}]},{"n":8,"slug":"marrow-and-pin","kind":"site","lane":"loud","trade":"Tattoo studio","mobile":true,"group":"Websites · Loud","name":"Marrow & Pin","biz":"Tattoo studio, Bristol","c":"#F0386B","sheet":"#FDE3EA","cInk":"#141416","cText":"#DA3463","short":"A tattoo studio whose flash wall inks itself, stencil to black, as you scroll.","long":"A private studio site in black and bone with one pink for booking. The first screen is a real photo of a stencil going on skin, with a flash sheet pinned over it that inks itself as the page opens. Nine more sheets on the wall draw themselves from purple stencil to black as they come into view, two healed pieces have their real stencils laid back over them to drag across, and any sheet carries straight into a consultation form with the placement picked on a body outline.","proves":"Your own drawings can be the website, and they can still take the booking.","tags":["Flash that inks itself","Stencil over the healed piece","Placement on a body outline"],"tk":"tattoo","show":[{"scroll":"#wall","say":"Each sheet inks itself, stencil to black"},{"tap":"button[data-f=joss]","say":"Filter the wall by artist"},{"set":"#pair .frame input","to":12,"say":"Lay the stencil back over the healed piece"},{"tap":"button[data-i=\"6\"]","say":"Open a sheet for sizes"}]},{"n":9,"slug":"hale-and-partners","kind":"site","lane":"quiet","trade":"Accountant","mobile":true,"group":"Websites · Quiet","name":"Hale & Partners","biz":"Chartered accountants, Harrogate","c":"#12B76A","sheet":"#DEF5EA","cInk":"#141416","cText":"#137F4D","short":"An accountant's site that counts down to your next deadline from the first screen.","long":"A practice site in ledger navy and white with one green for anything on time. The first screen shows a real office and the next tax deadline counted in days from the day you open the page, with the two after it underneath. Seven services sit as a ledger of what you hand over and what you get back, three questions light up the one to start with, and a sample year end settles from last year's figures to this year's before ticking itself filed.","proves":"The dates and the figures do the selling. Nothing else has to.","tags":["Deadlines counted from today","Three-question triage","Year end that settles"],"tk":"accountant","show":[{"scroll":".next","say":"The next deadline, counted from today"},{"tap":"button[data-v=ltd]","say":"Say what you run"},{"tap":"button[data-v=dead]","say":"And what is worrying you"},{"tap":"button[data-v=cloud]","say":"The line to start with lights up"}]},{"n":10,"slug":"fern-physio","kind":"site","lane":"quiet","trade":"Physiotherapy clinic","mobile":true,"group":"Websites · Quiet","name":"Fern Physio","biz":"Fern Physio","c":"#14B8A6","sheet":"#DEF5F3","cInk":"#141416","cText":"#148074","short":"A drawn body with ten tappable points, and a booking flow behind it.","long":"A two-room physiotherapy clinic where the hero is a line-drawn standing figure, front and back, with ten points you can tap. Each one names what the problem usually turns out to be and what the physio would actually do, and the next three free slots for that area sit right beside it, one tap from booked. Real treatment photos, the price list and both physios follow on a crisp white page. The diary is generated from the real clock, so the slots are never stale.","proves":"A visitor can say where it hurts before they have to say anything to a receptionist.","tags":["quiet","booking","body map"],"tk":"clinic","show":[{"tap":"button[data-r=shoulder]","say":"Tap where it hurts"},{"scroll":".pbook","say":"The next free slots sit right beside it"},{"tap":".pslot","say":"One tap and it is booked in"}]},{"n":11,"slug":"kestrel-electrical","kind":"site","lane":"direct","trade":"Electrician","mobile":true,"group":"Websites · Direct","name":"Kestrel Electrical","biz":"Two-van electrical firm","c":"#C8F031","sheet":"#F7FDE2","cInk":"#141416","cText":"#6A7D23","short":"An electrician's page built as a fuse board: every job is a breaker.","long":"Real photos, the phone number at poster size and a three-field call-back up top. The services are a full-width consumer unit: flip a breaker and it switches on to show what's included, what it costs and a button to ring about it. The circuit chart beside it is the price list. The only things that move are switches.","proves":"Someone standing in a dark kitchen can ring the right number in one tap, at any hour, without reading a word of marketing.","tags":["Breaker board","Three-field callback","Postcode area check","Open-now line switching"],"tk":"electrician","show":[{"tap":"button[data-c=\"2\"]","say":"Flip a breaker"},{"tap":"button[data-c=\"6\"]","say":"The emergency one"}]},{"n":12,"slug":"kerb-and-camber","kind":"site","lane":"direct","trade":"Garage","mobile":true,"group":"Websites · Direct","name":"Kerb & Camber","biz":"Kerb & Camber MOT Centre","c":"#F6C700","sheet":"#FEF7DB","cInk":"#141416","cText":"#8C730A","short":"A UK number plate you type into, and the MOT date that comes back.","long":"An independent MOT and service centre where the hero is a real number plate you can type in. Press Check and a job card comes back with the vehicle, the last advisory, how many days until the MOT runs out, and the next three slots on the ramp. Below it sit the price board from the office door, each line with its own Book button, the clock times of a real MOT from keys to away, and a half-hour diary. On a phone the call and book buttons never leave the screen.","proves":"Somebody who does not know when their MOT is due can find out and book it before they close the tab.","tags":["direct","reg lookup","booking"],"tk":"garage","show":[{"type":"#reg","text":"KX19 LBD","say":"Put your reg in"},{"tap":"#checkBtn","say":"It tells you when the MOT is due"}]},{"n":13,"slug":"system","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"The system","biz":"Six made-up service businesses","c":"#2563EB","sheet":"#E0E9FC","cInk":"#FFFFFF","cText":"#2563EB","short":"One screen: every call caught, every job booked, and what still needs you.","long":"The app a service business runs on, shown for six made-up businesses. Today puts the whole day on one board in the business’s own colour: every missed call caught, every booking made and every quote won since the morning, and the work it added up to. It replays the morning in a few seconds, and new enquiries and bookings keep landing while you watch. Switch business from the menu and it all reloads for that trade.","proves":"The admin happens while you are on the tools.","tags":["Six businesses","Live from the clock","Every part connected"],"tk":"any","show":[{"tap":"#tdPlay","say":"Replay the morning","pause":300},{"wait":7500,"say":"Every call caught and every job booked, as it happened"},{"wait":8500,"say":"New work keeps landing while you watch"},{"tap":"#todaySim","say":"Try a missed call yourself","pause":400},{"wait":6500,"say":"It texts them back in seconds"}]},{"n":14,"slug":"inbox","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Inbox and missed calls","biz":"Six made-up service businesses","c":"#2563EB","sheet":"#E0E9FC","cInk":"#FFFFFF","cText":"#2563EB","short":"Every call, text and form in one list. Missed calls get a text back in seconds.","long":"Press “Simulate a missed call” and watch it happen: the phone rings out, a countdown runs, the text goes from the business’s own number, and the customer replies. One tap sends the booking link, and the booking lands in the diary with its deposit.","proves":"The customer gets a text before they ring the next name on Google.","tags":["Missed-call text-back","One inbox","Booking link"],"tk":"any","show":[{"tap":"#simCall","say":"Simulate a missed call","pause":400},{"wait":7000,"say":"A text goes back in seconds, from the business’s own number"},{"wait":4500,"say":"They reply"},{"tap":"#inLink","say":"One tap sends the booking link","pause":400},{"wait":5500,"say":"They book and pay the deposit"}]},{"n":15,"slug":"booking","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Booking and the diary","biz":"Six made-up service businesses","c":"#2563EB","sheet":"#E0E9FC","cInk":"#FFFFFF","cText":"#2563EB","short":"Customers book a real free time and pay a deposit. It lands in the right diary.","long":"A diary with a lane for each person, travel time between jobs, and the deposit on every online booking. Book as a customer from their phone and watch the slot appear; move a job, send an on-my-way text, or mark it done and the review ask queues itself.","proves":"Nobody books and vanishes, and nobody plays phone tag for a time.","tags":["Online booking","Deposits","Team diary"],"tk":"any","show":[{"tap":"#bkTry","say":"Book online, as a customer would"},{"tap":".bk-po","say":"Pick the job","pause":600},{"tap":"#bkT-0","say":"Pick a free time","pause":600},{"tap":"#bkPay","say":"Pay the deposit","pause":1200},{"tap":"#bkDone","say":"It is in the diary, marked new"}]},{"n":16,"slug":"quotes","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Quotes that chase themselves","biz":"Six made-up service businesses","c":"#2563EB","sheet":"#E0E9FC","cInk":"#FFFFFF","cText":"#2563EB","short":"Quotes from your price list that chase themselves until the customer answers.","long":"Quotes built from the business’s own price list with VAT and a deposit. Send one and watch it get opened; it chases at 9am on day two and day five until the customer answers, then stops the moment they accept and pay the deposit.","proves":"Fewer quotes go cold while you are busy.","tags":["Price list","Automatic chasing","Accept and pay"],"tk":"any","show":[{"tap":"#qNew","say":"Start a quote from your own template"},{"tap":"#qSend","say":"Send it: the customer gets a link","pause":400},{"wait":4500,"say":"Opened, and the chasing is booked in"},{"tap":"#qPhone","say":"What the customer sees"},{"tap":"#qAccept","say":"They accept and pay the deposit. The chasing stops."}]},{"n":17,"slug":"reviews","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Google reviews","biz":"Six made-up service businesses","c":"#2563EB","sheet":"#E0E9FC","cInk":"#FFFFFF","cText":"#2563EB","short":"Every finished job asks for a review. Replies take one tap.","long":"After each job the customer gets a short text with a link to leave a Google review. Every customer is asked, not only the happy ones, because Google’s rules ban picking. New reviews land here with a reply already written to edit and post.","proves":"More reviews, and recent ones, keep you near the top of the map.","tags":["Review asks","One-tap replies","Rating over time"],"tk":"any","show":[{"tap":"#rvSend","say":"Every finished job gets a review text","pause":400},{"wait":6500,"say":"A new five-star review lands"},{"tap":"#rvList [data-act=reply]","say":"The reply is drafted with their name and the job"},{"tap":"#rvPost","say":"Post it"}]},{"n":18,"slug":"reminders","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Reminders that rebook","biz":"Six made-up service businesses","c":"#2563EB","sheet":"#E0E9FC","cInk":"#FFFFFF","cText":"#2563EB","short":"Yearly services, MOTs and regular cuts remind the customer and book themselves.","long":"Repeat work comes round on its own: the boiler service, the MOT, the six-weekly cut. The customer gets a reminder before it is due and books from the link; the booking drops into the diary without a phone call.","proves":"Last year’s customers come back before they search.","tags":["Due dates","Reminder texts","Rebooked jobs"],"tk":"any","show":[{"tap":"#rmSend","say":"Reminders go out before the work is due","pause":400},{"wait":5500,"say":"Customers book themselves in from the text"},{"tap":"#rmList .rm-row","say":"Each one: the text, its history and the free times"}]},{"n":19,"slug":"results","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Results and ads","biz":"Six made-up service businesses","c":"#2563EB","sheet":"#E0E9FC","cInk":"#FFFFFF","cText":"#2563EB","short":"Where every job came from, what it was worth, and what the ads cost per job.","long":"A month-by-month view of where the work came from: Google Ads, Meta ads, the map, the website, referrals and repeat customers, with enquiries, bookings, the money booked and the cost per job. The monthly report writes itself in plain English. Demo figures for a made-up business.","proves":"You can see which pound of ad spend booked which job.","tags":["By source","Cost per job","Monthly report"],"tk":"any","show":[{"tap":"#rsMonth [data-i=\"4\"]","say":"Pick a month"},{"scroll":"#rsChain","say":"From enquiry to booked work"},{"tap":"#rsReport","say":"The monthly report, in plain English"}]}];